import ProfessionalCard from "../components/ProfessionalCard";
import "./Hire.css";

export default function Hire() {
  return (
    <div className="page">
      <h1>Hire Professionals</h1>

      <div className="pro-grid">
        <ProfessionalCard name="Rahul Singh" skill="Electrician" img="/p1.jpg" />
        <ProfessionalCard name="Amit Kumar" skill="Plumber" img="/p2.jpg" />
        <ProfessionalCard name="Sneha Jain" skill="Cleaner" img="/p3.jpg" />
      </div>
    </div>
  );
}
